def extract_text(document_path, client):
    with open(document_path, 'rb') as document:
        image_bytes = document.read()
    response = client.detect_document_text(Document={'Bytes': image_bytes})
    return response

def extract_layout(document_path, client):
    with open(document_path, 'rb') as document:
        image_bytes = document.read()
    response = client.analyze_document(Document={'Bytes': image_bytes}, FeatureTypes=['TABLES', 'FORMS'])
    return response

import boto3

def extract_key_values(document):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS'])
    key_values = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    key = None
                    value = None
                    for child_id in relationship['Ids']:
                        child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                        if child_block['BlockType'] == 'WORD':
                            if key is None:
                                key = child_block['Text']
                            else:
                                value = child_block['Text']
                    if key and value:
                        key_values[key] = value
    return key_values

import boto3

def extract_text_from_image(image_path):
    textract_client = boto3.client('textract')

    with open(image_path, 'rb') as image:
        image_bytes = image.read()

    response = textract_client.detect_document_text(
        Document={'Bytes': image_bytes}
    )

    extracted_text = ''
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            extracted_text += item['Text'] + ' '
    return extracted_text
